CREATE COLUMN TABLE "TEST_AP"."OFPR" ("AbsEntry" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(20) NOT NULL , "Name" NVARCHAR(20) NOT NULL , "F_RefDate" LONGDATE CS_LONGDATE, "T_RefDate" LONGDATE CS_LONGDATE, "F_DueDate" LONGDATE CS_LONGDATE, "T_DueDate" LONGDATE CS_LONGDATE, "F_TaxDate" LONGDATE CS_LONGDATE, "T_TaxDate" LONGDATE CS_LONGDATE, "Free2" NVARCHAR(1) DEFAULT 'Y', "Free3" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "SubNum" INTEGER CS_INT, "Free" NVARCHAR(1), "Free1" NVARCHAR(1), "Addition" NVARCHAR(1) DEFAULT 'N', "AddNum" INTEGER CS_INT, "Category" NVARCHAR(10), "Indicator" NVARCHAR(10), "LogInstanc" INTEGER CS_INT DEFAULT 0, "UpdateDate" LONGDATE CS_LONGDATE, "WasStatChd" NVARCHAR(1) DEFAULT 'N', "PeriodStat" NVARCHAR(1) DEFAULT 'N', "UserSign2" SMALLINT CS_INT, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OFPR_CODE" ON "TEST_AP"."OFPR" ( "Code" ASC );
CREATE UNIQUE INDEX "OFPR_NAME" ON "TEST_AP"."OFPR" ( "Name" ASC )